package com.example.padautosolver;
import android.graphics.Bitmap;
/** Strict cyan-glyph comparison for the device-verified five-column sale layout. */
final class SaleVisuals {
    private static final String[] MP = {
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
"",
""
};
    static int selectedMp(Bitmap image) { return readMp(image, 80); }
    static int dialogRemainingMp(Bitmap image) { return readMp(image, 20); }
    private static int readMp(Bitmap image, int threshold) {
        if (image.getWidth() != 1220 || image.getHeight() != 2712) return -1;
        for (int value = 0; value < MP.length; value++) {
            int mismatch = 0;
            for (int y = 0; y < 27; y++) for (int x = 0; x < 40; x++) {
                int color = image.getPixel(842 + 2*x + 1, 2319 + 2*y + 1);
                int r = color >> 16 & 255, g = color >> 8 & 255, b = color & 255;
                boolean ink = g>threshold && b>threshold && g>r*1.5 && b>r*1.5;
                if (ink != (MP[value].charAt(y*40+x)=='1')) mismatch++;
            }
            if (mismatch <= 6) return value;
        }
        return -1;
    }
}
